// Validate factory webhook input + derive hook identity
//
// Hook detection trigger: action with low success_rate (repeated mistake pattern)
// Hook will be a PreToolUse guard preventing the failure pattern.

const body = $input.first().json.body || $input.first().json;
const pattern = body.pattern;

if (!pattern || !pattern.action) {
  throw new Error('pattern.action required');
}

// Derive hook name from failure action
// e.g., 'env_var_drift_failed' → 'prevent-env-var-drift'
const slug = String(pattern.action)
  .toLowerCase()
  .replace(/_(failed|error|aborted|rejected)$/, '')
  .replace(/_/g, '-')
  .replace(/[^a-z0-9-]/g, '');

const hookName = `prevent-${slug}`;
const hookPath = `.claude/hooks/${hookName}.sh`;

// Registration target for .claude/settings.json (consumed by WF_AISHA_TOOLING_COMMITTER
// via metadata.settings_patch). Factory hooks are PRE-emptive edit guards, so they
// register as PreToolUse on Edit|Write|MultiEdit unless the detected pattern overrides it.
const hookEvent = pattern.hook_event || 'PreToolUse';
const hookMatcher = pattern.hook_matcher || 'Edit|Write|MultiEdit';

return [{
  json: {
    hook_name: hookName,
    hook_path: hookPath,
    hook_event: hookEvent,
    hook_matcher: hookMatcher,
    pattern,
    occurrence_count: pattern.occurrence_count || 0,
    success_rate: pattern.success_rate || 0,
    requested_at: new Date().toISOString(),
  },
}];

