parameters.jsCode:
// Validate generated bash hook
const response = $input.first().json;
const content = response.content?.[0]?.text;

if (!content) {
  throw new Error('No content from Anthropic response');
}

// Strip optional code fences (Anthropic sometimes adds them despite instructions)
let cleanContent = content
  .replace(/^```(?:bash|sh)?\n?/m, '')
  .replace(/\n?```\s*$/m, '')
  .trim();

// Add trailing newline
if (!cleanContent.endsWith('\n')) cleanContent += '\n';

const networkPatterns = /\b(curl\s|wget\s|nc\s|ssh\s|scp\s|sftp\s|rsync\s)/;

const validation = {
  has_shebang: /^#!\/usr\/bin\/env bash|^#!\/bin\/bash/.test(cleanContent),
  has_strict_mode: /set -euo pipefail/.test(cleanContent),
  reads_hook_input: /CLAUDE_HOOK_TOOL_INPUT/.test(cleanContent),
  no_network: !networkPatterns.test(cleanContent),
  has_exit_code: /exit\s+[0-9]/.test(cleanContent),
  passed: false,
};

validation.passed = validation.has_shebang &&
  validation.has_strict_mode &&
  validation.reads_hook_input &&
  validation.no_network &&
  validation.has_exit_code;

return [{
  json: {
    ...$('Validate + Derive Identity').item.json,
    rendered_content: cleanContent,
    validation,
  },
}];

